foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);$nl=if($x.Contains("`r`n")){"`r`n"}else{"`n"};foreach($c in $t.changes){$c.from=$c.from.Replace("`n",$nl);$c.to=$c.to.Replace("`n",$nl);if($x.Contains($c.from)){$x=$x.Replace($c.from,$c.to)}elseif($c.to -ne '' -and -not$x.Contains($c.to)){throw "Block/renderer ABI anchor missing in $($t.rel): $($c.from)"}};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;foreach($c in $t.changes){if(-not(@($e.changes)|Where-Object {$_.from -eq $c.from -and $_.to -eq $c.to})){$e.changes=@($e.changes)+$c}};if($e.PSObject.Properties.Name -contains 'status'){$e.status=$t.status}else{$e|Add-Member -NotePropertyName status -NotePropertyValue $t.status}}
$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Cleaned block codec and renderer/behaviour ABI tail.'
